ALTER ASSEMBLY AzureBankClr
FROM 'D:\clr\AzureBank.Clr.dll'
WITH PERMISSION_SET = SAFE, UNCHECKED DATA;

ALTER DATABASE AUDIT SPECIFICATION AzureBankUserAccess
FOR SERVER AUDIT AzureBankAudit
ADD (DATABASE_OBJECT_CHANGE_GROUP);

ALTER DATABASE AzureBank
SET SINGLE_USER
WITH ROLLBACK IMMEDIATE;

ALTER DATABASE AzureBank SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
DBCC CHECKDB (N'AzureBank', REPAIR_REBUILD);
ALTER DATABASE AzureBank SET MULTI_USER;

ALTER EVENT SESSION AzureBankDeadlocks
ON SERVER
STATE = START;

ALTER INDEX IX_AuditEvents_Sequence
ON dbo.AuditEvents
REBUILD WITH (FILLFACTOR = 90, SORT_IN_TEMPDB = ON);

