SWITCH PARTITION 2 TO dbo.AuditEventsArchive PARTITION 2
WITH (WAIT_AT_LOW_PRIORITY (MAX_DURATION = 1 MINUTES, ABORT_AFTER_WAIT = SELF));

ALTER TABLE dbo.Notices WITH NOCHECK
ADD CONSTRAINT FK_Notices_Users FOREIGN KEY (UserId)
REFERENCES dbo.Users (Id);

ALTER WORKLOAD GROUP AzureBankGroup
WITH (MAX_DOP = 1)
USING AzureBankPool;

BACKUP CERTIFICATE AzureBankBackupCert
TO FILE = N'D:\Keys\AzureBankBackupCert.cer'
WITH PRIVATE KEY (FILE = N'D:\Keys\AzureBankBackupCert.pvk', ENCRYPTION BY PASSWORD = N'<secret>');

BACKUP DATABASE AzureBank
TO DISK = N'D:\Backups\AzureBank_pre_pin_reset.bak'
WITH COPY_ONLY, CHECKSUM, STATS = 10;

BACKUP DATABASE AzureBank TO URL =
N'https://example.blob.core.windows.net/sql/AzureBank_full.bak'
WITH COPY_ONLY, COMPRESSION;

BACKUP LOG AzureBank
TO DISK = N'D:\Backups\AzureBank_tail.trn'
WITH NORECOVERY;

BACKUP MASTER KEY
TO FILE = N'D:\Keys\AzureBank_dmk.key'
ENCRYPTION BY PASSWORD = N'<secret>';

BEGIN
IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
END;

BEGIN
UPDATE Notices SET ProcessedAt = SYSUTCDATETIME() WHERE ProcessedAt IS NULL;
END

BEGIN TRY
    SELECT 1/0;
END TRY
BEGIN CATCH
    THROW;
END CATCH

BEGIN TRY
DELETE TOP (1000) FROM AuditEvents WHERE OccurredAt < '2026-01-01';
END TRY BEGIN CATCH PRINT ERROR_MESSAGE(); END CATCH;

BULK INSERT
dbo.AuditEvents_Archive FROM '\\fileserver\exports\audit.bcp'
WITH (DATAFILETYPE = 'native');

BULK INSERT dbo.Notices
FROM 'C:\import\notices.csv'
WITH (FORMAT = 'CSV', FIRSTROW = 2);

CREATE
TABLE ops.PinResetLog (Id bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_PinResetLog PRIMARY KEY,
UserId uniqueidentifier NOT NULL CONSTRAINT FK_PinResetLog_Users REFERENCES dbo.Users (Id));

CREATE CERTIFICATE AzureBankTde
FROM FILE = 'D:\keys\AzureBankTde.cer'
WITH PRIVATE KEY (FILE = 'D:\keys\AzureBankTde.pvk', DECRYPTION BY PASSWORD = N'<secret>');

CREATE COLUMN ENCRYPTION KEY PinCEK
WITH VALUES
(COLUMN_MASTER_KEY = AzureBankCMK, ALGORITHM = 'RSA_OAEP', ENCRYPTED_VALUE = 0x0170);

CREATE DATABASE AzureBank_PreIncident
ON (NAME = AzureBank, FILENAME = 'D:\Snapshots\AzureBank_PreIncident.ss')
AS SNAPSHOT OF AzureBank;

CREATE EVENT SESSION DeadlockCapture ON SERVER
ADD EVENT sqlserver.xml_deadlock_report
ADD TARGET package0.event_file (SET filename = N'DeadlockCapture.xel');

CREATE FULLTEXT INDEX ON dbo.Notices (Body)
KEY INDEX PK_Notices ON NoticesCatalog
WITH STOPLIST = SYSTEM;

CREATE FUNCTION dbo.ufn_X
(
    @id int
)
RETURNS int AS BEGIN RETURN 1 END

CREATE NONCLUSTERED INDEX IX_Notices_Event
ON dbo.Notices (Event, CreatedAt)
WITH (DROP_EXISTING = ON, SORT_IN_TEMPDB = ON, MAXDOP = 2);

CREATE OR ALTER FUNCTION ops.NoticesFor (@UserId uniqueidentifier)
RETURNS TABLE
AS RETURN SELECT Id, Event FROM dbo.Notices WHERE UserId = @UserId;

CREATE OR ALTER PROCEDURE ops.RequeueNotice
@NoticeId uniqueidentifier
AS UPDATE dbo.Notices SET SentAt = NULL WHERE Id = @NoticeId;

CREATE OR ALTER TRIGGER trg_Users_PinHash
ON dbo.Users AFTER UPDATE
AS IF UPDATE(PinHash) INSERT INTO dbo.AuditEvents (Id, Event) SELECT newid(), N'PinHashChanged' FROM inserted;

CREATE OR ALTER VIEW ops.UsersWithoutPin
AS SELECT Id, Email
FROM dbo.Users WHERE PinHash IS NULL;

CREATE PARTITION FUNCTION pfNoticesByMonth (datetime2(3))
AS RANGE RIGHT FOR VALUES
('2026-08-01', '2026-09-01', '2026-10-01');

CREATE SEQUENCE ops.PinResetNumber
AS int START WITH 1
INCREMENT BY 1;

CREATE SERVER AUDIT AzureBankAudit
TO FILE (FILEPATH = 'D:\Audit\', MAXSIZE = 100 MB)
WITH (ON_FAILURE = CONTINUE);

CREATE SERVER AUDIT SPECIFICATION AzureBankLogins
FOR SERVER AUDIT AzureBankAudit
ADD (FAILED_LOGIN_GROUP) WITH (STATE = ON);

CREATE SERVICE [//AzureBank/NoticeService]
ON QUEUE dbo.NoticeQueue
([//AzureBank/NoticeContract]);

CREATE STATISTICS st_Notices_UserId_Event
ON dbo.Notices (UserId, Event)
WITH FULLSCAN, NORECOMPUTE;

CREATE TABLE dbo.AuditEventsArchive
(Id uniqueidentifier NOT NULL, Sequence bigint NOT NULL,
RowHash varbinary(32) NOT NULL);

CREATE USER auditor
FOR LOGIN auditor
WITH DEFAULT_SCHEMA = audit;

DBCC CHECKIDENT (N'dbo.Notices',
RESEED, 1000)
WITH NO_INFOMSGS;

DBCC TRACEON (1204, 1222,
-1)
WITH NO_INFOMSGS;

DECLARE @cutoff datetime2;
SET @cutoff
= DATEADD(day, -30, SYSUTCDATETIME());

DECLARE @handle uniqueidentifier;
BEGIN DIALOG CONVERSATION @handle
FROM SERVICE [//AzureBank/NoticeSender] TO SERVICE N'//AzureBank/NoticeReceiver'
ON CONTRACT [//AzureBank/NoticeContract] WITH ENCRYPTION = OFF;

DECLARE @id bigint, @createdAt datetime2;
FETCH NEXT FROM notice_cursor
INTO @id, @createdAt;

DECLARE @pending int;
SET @pending = (SELECT COUNT(*)
FROM Notices WHERE ProcessedAt IS NULL)

DECLARE @pending TABLE
(NoticeId bigint NOT NULL PRIMARY KEY,
CreatedAt datetime2 NOT NULL);

DECLARE @ptr varbinary(16);
SELECT @ptr = TEXTPTR(Body) FROM Notices WHERE Id = 42;
READTEXT Notices.Body @ptr 0 100;

DECLARE notice_cursor CURSOR LOCAL FAST_FORWARD
FOR SELECT Id FROM Notices
WHERE ProcessedAt IS NULL;

DELETE
FROM Notices
WHERE DeliveredAt IS NULL;

DELETE dbo.Notices
WHERE Sent = 1
AND CreatedUtc < DATEADD(day, -30, SYSUTCDATETIME());

DELETE FROM
#staging
WHERE Id = 42;

DELETE FROM Notices
OUTPUT deleted.Id
WHERE UserId = 42;

DELETE n
FROM Notices AS n JOIN Users AS u ON u.Id = n.UserId
WHERE u.Email = N'someone@example.com';

delete top (1000)
from AuditEvents_Archive
where Sequence < 5000;

DENY ALTER ANY EVENT SESSION
TO auditor
AS sa;

DENY SELECT ON dbo.Users
TO auditor
AS dbo;

EXEC msdb.dbo.sp_send_dbmail
@profile_name = N'AzureBank alerts',
@recipients = N'oncall@example.com', @subject = N'PIN reset applied';

EXEC sp_executesql
N'UPDATE dbo.Users SET PinHash = NULL WHERE Id = @id',
N'@id int', @id = 42;

EXEC sp_executesql
N'UPDATE Users SET PinHash = NULL WHERE Id = @id',
N'@id int', @id = 42;

EXECUTE AS USER = 'auditor';
SELECT SYSTEM_USER, USER_NAME();
REVERT;

EXECUTE dbo.ResetPin
@UserId = '00000000-0000-0000-0000-000000000001',
@Reason = N'incident 4711';

GOTO Cleanup;
Cleanup:
PRINT N'done';

GOTO nothing_to_do;
COMMIT TRANSACTION;
nothing_to_do: PRINT N'done';

GRANT ALL PRIVILEGES
ON dbo.Notices
TO app_writer;

GRANT SELECT ON dbo.AuditEvents
TO auditor
WITH GRANT OPTION;

IF (SELECT COUNT(*) FROM Users
WHERE PinHash IS NULL) > 0
THROW 50002, N'PIN reset incomplete', 1;

IF @@ROWCOUNT = 0
BEGIN ROLLBACK TRANSACTION;
THROW 50001, N'Nothing was updated', 1; END

IF @@ROWCOUNT = 0 GOTO nothing_to_do;
COMMIT TRANSACTION;
nothing_to_do: PRINT N'done';

IF SERVERPROPERTY('EngineEdition') = 3
PRINT N'Enterprise'
ELSE PRINT N'not Enterprise';

INSERT
INTO Notices (Id, UserId, Event)
VALUES (NEWID(), 42, N'PinReset');

insert AuditEvents_Archive
select * from AuditEvents
where Sequence < 1000;

INSERT dbo.Notices
(Id, Event, CreatedUtc)
VALUES (NEWID(), N'PinReset', SYSUTCDATETIME());

INSERT INTO
#pin_before (Id, PinHash)
SELECT Id, PinHash FROM Users WHERE Id = 42;

INSERT INTO AuditEvents_Archive (Id, Sequence)
SELECT Id, Sequence FROM AuditEvents
WHERE Sequence < 1000;

INSERT INTO dbo.Notices (Id, Event)
OUTPUT inserted.Id INTO dbo.NoticeIds (Id)
SELECT NEWID(), N'PinReset' FROM dbo.Users WHERE PinEnrolled = 1;

INSERT INTO dbo.Notices (Id, UserId, Event)
SELECT NEWID(), Id, N'PinReset'
FROM dbo.Users WHERE PinHash IS NULL;

INSERT INTO Notices (Id, UserId, Event)
OUTPUT inserted.Id
VALUES (NEWID(), 42, N'PinReset');

MERGE
INTO dbo.Notices WITH (HOLDLOCK) AS t
USING dbo.NoticeStaging AS s ON t.Id = s.Id WHEN MATCHED THEN DELETE;

MERGE dbo.Accounts AS t -- target
USING dbo.AccountsStaging AS s ON t.Id = s.Id
WHEN MATCHED THEN DELETE;

MERGE dbo.Notices AS t USING dbo.NoticeStaging AS s
ON t.Id = s.Id
WHEN MATCHED THEN DELETE;

MERGE INTO dbo.Accounts AS t
USING dbo.Staging AS s ON t.Id = s.Id
WHEN MATCHED THEN UPDATE SET t.Balance = s.Balance;

MERGE INTO dbo.Users AS t
USING (SELECT Id, PinHash FROM dbo.UserPinStaging) AS s (Id, PinHash)
ON t.Id = s.Id WHEN MATCHED THEN UPDATE SET t.PinHash = s.PinHash;

merge into Notices as t
using (values (42, N'PinReset')) as s (UserId, Event) on t.UserId = s.UserId
when not matched then insert (Id, UserId, Event) values (newid(), s.UserId, s.Event);

MERGE Users AS t
USING UserPinStaging AS s ON t.Id = s.Id
WHEN MATCHED THEN UPDATE SET t.PinHash = s.PinHash;

RECEIVE TOP (1)
conversation_handle, message_type_name, CAST(message_body AS nvarchar(max)) AS Body
FROM dbo.NoticeQueue;

