NULL 0
N' (reissued)';

WHILE (SELECT COUNT(*) FROM Notices WHERE ProcessedAt IS NULL) > 0
BEGIN WAITFOR DELAY '00:00:10';
END

WHILE 1 = 1
BEGIN DELETE TOP (500) FROM Notices WHERE ProcessedAt IS NOT NULL;
IF @@ROWCOUNT = 0 BREAK; END

WHILE 1 = 1 BEGIN
CONTINUE;
END

WHILE EXISTS (SELECT 1 FROM Notices
WHERE ProcessedAt IS NULL)
WAITFOR DELAY '00:00:30';

WITH
pending AS (SELECT TOP (100) * FROM Notices WHERE DeliveredAt IS NULL)
UPDATE pending SET DeliveredAt = SYSUTCDATETIME();

WITH chain (Sequence, RowHash) AS (
SELECT Sequence, RowHash FROM dbo.AuditEvents
) SELECT COUNT(*) FROM chain

with dupes as
(select Id, row_number() over (partition by Email order by Id) as rn from Users)
delete from dupes where rn > 1;

WITH recent AS (
SELECT TOP 5 * FROM AuditEvents ORDER BY Sequence DESC)
SELECT * FROM recent;

WITH recent AS (SELECT TOP 5 * FROM AuditEvents),
older AS (SELECT TOP 5 * FROM AuditEvents_Archive)
SELECT * FROM recent UNION ALL SELECT * FROM older;

WITH src (Id, PinHash)
AS (SELECT Id, PinHash FROM UserPinStaging)
SELECT * FROM src;

